/**
 * Orders Service - Database Row Types
 *
 * Type definitions for Supabase database tables related to orders.
 * These types map directly to the database schema using snake_case.
 *
 * @module orders.types
 */

/**
 * Database row type for the 'orders' table
 *
 * Maps directly to Supabase orders table schema.
 * Uses snake_case to match database column naming convention.
 */
export interface OrderRow {
  /** Primary key - UUID generated by database */
  id: string;

  /** Foreign key to users table (null for guest orders) */
  user_id: string | null;

  /** Customer's full name */
  customer_name: string;

  /** Customer's email address */
  customer_email: string;

  /** Customer's phone number (optional) */
  customer_phone: string | null;

  /** Shipping/delivery address (optional) */
  shipping_address: string | null;

  /** Subtotal before shipping */
  subtotal: number;

  /** Shipping cost */
  shipping_cost: number;

  /** Total order amount (subtotal + shipping) */
  total: number;

  /** Current order status */
  status: string;

  /** Payment method used */
  payment_method: string;

  /** Current payment status */
  payment_status: string;

  /** Additional order notes (optional) */
  notes: string | null;

  /** Timestamp when order was created */
  created_at: string;

  /** Timestamp when order was last updated */
  updated_at: string;
}

/**
 * Database row type for the 'order_items' table
 *
 * Contains individual items within an order.
 * Each row represents one product in an order.
 */
export interface OrderItemRow {
  /** Primary key - UUID generated by database */
  id: string;

  /** Foreign key to orders table */
  order_id: string;

  /** Foreign key to products table (null if product deleted) */
  product_id: string | null;

  /** Product name stored at time of order */
  product_name: string;

  /** Quantity ordered */
  quantity: number;

  /** Price per unit at time of order */
  unit_price: number;

  /** Total price for this line item (quantity * unit_price) */
  total_price: number;

  /** Timestamp when item was added */
  created_at: string;
}

/**
 * Input type for creating a new order in the database
 *
 * Contains only the fields needed for order creation.
 * Excludes id, timestamps which are auto-generated.
 */
export interface CreateOrderInput {
  /** Foreign key to users table (null for guest orders) */
  user_id: string | null;

  /** Customer's full name */
  customer_name: string;

  /** Customer's email address */
  customer_email: string;

  /** Customer's phone number (optional) */
  customer_phone: string | null;

  /** Shipping/delivery address (optional) */
  shipping_address: string | null;

  /** Subtotal before shipping */
  subtotal: number;

  /** Shipping cost */
  shipping_cost: number;

  /** Total order amount (subtotal + shipping) */
  total: number;

  /** Current order status */
  status: string;

  /** Payment method used */
  payment_method: string;

  /** Current payment status */
  payment_status: string;

  /** Additional order notes (optional) */
  notes: string | null;
}

/**
 * Input type for creating order items in the database
 *
 * Used when inserting multiple items for an order.
 */
export interface CreateOrderItemInput {
  /** Foreign key to orders table */
  order_id: string;

  /** Foreign key to products table (null if product deleted) */
  product_id: string | null;

  /** Product name stored at time of order */
  product_name: string;

  /** Quantity ordered */
  quantity: number;

  /** Price per unit at time of order */
  unit_price: number;

  /** Total price for this line item */
  total_price: number;
}

/**
 * Order statistics returned by getOrderStats
 */
export interface OrderStats {
  /** Total number of orders */
  total: number;

  /** Number of orders with pending status */
  pending: number;

  /** Number of orders with processing status */
  processing: number;

  /** Number of orders with shipped status */
  shipped: number;

  /** Number of orders with delivered status */
  delivered: number;

  /** Number of orders with cancelled status */
  cancelled: number;

  /** Total revenue from paid orders */
  totalRevenue: number;
}

/**
 * Status update options for orders
 */
export type OrderStatusUpdate = {
  status: string;
};

/**
 * Payment status update options for orders
 */
export type PaymentStatusUpdate = {
  payment_status: string;
};
